1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("should return no living cells for an empty grid", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("should let a single living cell die from underpopulation", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("should let two adjacent living cells die from underpopulation", () => {
12	    expect(
13	      nextGeneration([
14	        [0, 0],
15	        [1, 0],
16	      ]),
17	    ).toEqual([]);
18	  });
19	  it("should let a living cell with 2 live neighbors survive", () => {
20	    expect(
21	      nextGeneration([
22	        [0, 0],
23	        [1, 0],
24	        [2, 0],
25	      ]),
26	    ).toContainEqual([1, 0]);
27	  });
28	  it("should let a living cell with 3 live neighbors survive", () => {
29	    expect(
30	      nextGeneration([
31	        [0, 0],
32	        [1, 0],
33	        [0, 1],
34	        [1, 1],
35	      ]),
36	    ).toContainEqual([0, 0]);
37	  });
38	  it("should let a living cell with more than 3 live neighbors die from overpopulation", () => {
39	    expect(
40	      nextGeneration([
41	        [1, 1],
42	        [0, 1],
43	        [2, 1],
44	        [1, 0],
45	        [1, 2],
46	      ]),
47	    ).not.toContainEqual([1, 1]);
48	  });
49	  it("should bring a dead cell with exactly 3 live neighbors to life", () => {
50	    expect(
51	      nextGeneration([
52	        [0, 0],
53	        [1, 0],
54	        [0, 1],
55	      ]),
56	    ).toContainEqual([1, 1]);
57	  });
58	  it.todo("should keep a block still life unchanged");
59	  it.todo("should oscillate a blinker from vertical to horizontal");
60	  it.todo("should oscillate a blinker from horizontal back to vertical");
61	  it.todo("should handle cells at negative coordinates");
62	});
